public Map<String,String> getImageResources(){
  if (imageResources != null) {
    return imageResources;
  }
  try {
    ResourceBundle resourceBundle=ResourceBundle.getBundle(DEFAULT_IMAGE_RESOURCE_PATH);
    Map<String,String> resources=new TreeMap<String,String>();
    this.initResources(resourceBundle,resources);
    this.initImagePluginResources(resources);
    imageResources=resources;
    return resources;
  } catch (UnsupportedOperationException | IllegalArgumentException | NullPointerException | ClassCastException | IndexOutOfBoundsException e) {
    throw new RuntimeException("Failed to initialize image resources", e);
  }
}
